when.condition:
@{
          var auth = context.Request.Headers.GetValueOrDefault("Authorization", "");
          var jwt = auth.StartsWith("Bearer ") ? auth.Substring(7).AsJwt() : null;
          return jwt != null && (jwt.Issuer == "https://accounts.google.com" || jwt.Issuer == "accounts.google.com");
        }

return-response.set-body:
@{
            return new JObject(
              new JProperty("type", "https://github.com/azure-intelligence-domain/integration-platform/blob/main/docs/problems/staff-sign-in-required.md"),
              new JProperty("title", "Staff Sign-In Required"),
              new JProperty("status", 401),
              new JProperty("detail", "Sign in with a Google account of the staff domain, through the customer portal."),
              new JProperty("instance", context.Request.OriginalUrl.Path)
            ).ToString();
          }
